Item.method_code:
const itemTypeId = window.itemID;
await ArasModules.odataFetch('method.CuiAddItemTypeToTOC', {
	method: 'POST',
	body: JSON.stringify({ itemTypeId })
});

const itemTypeName = aras.getItemProperty(window.item, 'name');
const successMessage = aras.getResource('', 'toc_editor.itemtype_added', itemTypeName);
const notify = aras.getNotifyByContext(window);
notify(successMessage, { type: 'success' });

aras.getMainWindow().mainLayout.observer.notify('UpdateTOC');
